from pathlib import Path
import json

LANGS = ['sk', 'cs', 'en', 'de', 'es']
DATA = {lang: {} for lang in LANGS}
def row(key, values):
    parts = values.split('|')
    assert len(parts) == 5, (key, len(parts))
    for lang, value in zip(LANGS, parts): DATA[lang][key] = value

